QUESTS["yeonrak"] = {"name": "연락선의 화부", "start": "qb_start", "startChance": 0.06, "years": [1919, 1943], "loc": "bs_pier", "followChance": 0.08, "stages": {"met": {"event": "qb_meet", "place": "화부의 기별", "sub": "연락선 화부 강덕배가 꾸러미를 찾으러 왔다"}, "tail": {"event": "qb_tail", "place": "장수통의 그림자", "sub": "누군가 덕배의 뒤를 밟고 있다"}, "warned": {"event": "qb_ship", "place": "출항하는 밤", "sub": "꾸러미와 사람을 연락선에 태워야 한다", "chance": 0.7}, "late": {"event": "qb_raid", "place": "화부 숙소 급습", "sub": "수상경찰이 이미 덕배의 숙소로 향했다", "chance": 0.9}, "caught": {"event": "qb_prison", "place": "부산형무소 면회", "sub": "덕배가 붙잡혀 갔다"}, "success": {"event": "qb_epilogue", "place": "상해에서 온 엽서", "sub": "바다 건너에서 소식이 왔다"}, "betray": {"event": "qb_revenge", "place": "", "sub": ""}}};
QUEST_EVENTS["qb_start"] = {"title": "석탄 자루 속 꾸러미", "kind": "quest", "loc": "bs_pier", "text": "부산 잔교. 시모노세키에서 들어온 연락선이 검은 연기를 토하며 부두에 붙는다.\n석탄 가루를 뒤집어쓴 사내 하나가 배 옆구리 쪽문으로 뛰어내려 부두 짐더미 사이로 내달린다. 그 뒤로 흰 제복의 수상경찰 둘이 호루라기를 불며 쫓아온다.\n사내가 당신 옆을 스치며 기름종이 꾸러미를 생선 함지 위로 툭 던진다. 눈이 마주친다. 시커먼 얼굴에 눈만 하얗다.\n“니, 이거 좀 맡아도. 사흘 뒤에 찾으러 오꾸마. 목숨줄이데이.”\n사내가 다시 뛰어간다. 수상경찰 하나가 함지 쪽을 힐끗 본다.", "options": [{"label": "꾸러미를 생선 함지 밑에 숨긴다", "check": {"stat": "agi", "diff": "normal"}, "ok": {"text": "고등어 사이로 꾸러미를 밀어 넣고 함지를 번쩍 들어 머리에 이었다.\n수상경찰이 다가와 함지를 들여다본다. 비린내에 얼굴을 찡그리며 손을 내젓는다. “가.”\n사흘 뒤 밤, 초량 판잣집 문을 두드리는 소리가 날 것이다.", "fx": {"heat": 1}, "quest": {"id": "yeonrak", "stage": "met", "wait": 5}}, "ng": {"text": "함지를 드는 순간 꾸러미 귀퉁이가 생선 사이로 삐져나왔다.\n“그게 뭐냐!” 수상경찰이 곤봉을 뽑아 든다.", "fight": "junsa", "dist": 2, "questFight": {"id": "yeonrak", "win": "met", "other": "met", "wait": 5}}}, {"label": "수상경찰에게 꾸러미를 건넨다", "ok": {"text": "꾸러미를 집어 수상경찰에게 내밀었다. “방금 저 사람이 던지고 갔소.”\n경찰이 꾸러미를 펴 보더니 눈이 커진다. 당신 손에 지폐 몇 장을 쥐여 준다.\n그날 저녁, 부두에서 석탄 가루를 뒤집어쓴 사내가 수갑을 차고 끌려가는 것을 보았다.", "fx": {"money": 6, "heat": -1}, "quest": {"id": "yeonrak", "stage": "betray", "wait": 7}}}, {"label": "못 본 척 지나간다", "ok": {"text": "꾸러미를 함지 위에 그대로 두고 자리를 떴다.\n돌아보니 수상경찰이 함지를 뒤지고 있었다. 생선 장수 할머니가 영문도 모른 채 끌려간다.\n가슴 한쪽이 무겁다.", "quest": {"id": "yeonrak", "stage": "end_ignored"}}}]};
QUEST_EVENTS["qb_meet"] = {"title": "화부 강덕배", "kind": "quest", "loc": "bs_home", "text": "사흘 뒤 밤, 초량 판잣집 문이 세 번 끊어 울린다. 문을 여니 그 사내다. 얼굴의 석탄 가루를 씻어 내니 생각보다 젊다.\n“강덕배라 칸다. 연락선 화부다. 배 밑창에서 석탄 퍼 넣는 사람이제.”\n꾸러미를 돌려주자 덕배가 기름종이를 조심스레 벗긴다. 접힌 종이 몇 장과 지폐 뭉치.\n“상해 임시정부로 갈 군자금 영수증하고 밀서다. 시모노세키 쪽 동지들이 모은 돈이고.”\n덕배가 목소리를 낮춘다.\n“다음 배 뜰 때까지 이걸 장수통 약방에 맡겨야 되는데, 내는 얼굴이 팔렸다. 그리고… 오늘 밤 내 잘 데가 없다.\"", "options": [{"label": "장수통 약방까지 꾸러미를 나른다", "check": {"stat": "agi", "diff": "normal"}, "ok": {"text": "꾸러미를 옷 속에 동여매고 산비탈 계단을 내려가 장수통으로 갔다.\n약방 주인이 말없이 꾸러미를 받아 약장 서랍 깊숙이 넣는다. “덕배한테 잘 받았다 전하소.”\n돌아오는 길, 등 뒤가 자꾸 서늘했다.", "fx": {"heat": 1}, "quest": {"id": "yeonrak", "stage": "tail", "wait": 4}}, "ng": {"text": "장수통 모퉁이에서 사복 형사와 눈이 마주쳤다.\n“거기, 잠깐. 그 배에 뭘 감췄나?\"", "fight": "hyungsa", "dist": 2, "questFight": {"id": "yeonrak", "win": "tail", "other": "tail", "wait": 4}}}, {"label": "판잣집에 덕배를 묵게 한다", "ok": {"text": "방 한쪽에 이불을 깔아 주었다. 덕배는 등을 벽에 붙이고 앉은 채 밤을 새웠다.\n새벽에 그가 일어서며 말한다. “니 같은 사람이 있어서 아직 할 만하다. 꾸러미는 내가 다른 길로 넘기꾸마.\"", "fx": {"heat": 2}, "quest": {"id": "yeonrak", "stage": "tail", "wait": 4}}}, {"label": "발을 뺀다", "ok": {"text": "“미안하오. 꾸러미 맡아 준 걸로 할 만큼 했소.”\n덕배가 고개를 끄덕인다. “맞다. 그것만도 고맙다. 오늘 내 본 건 잊어뿌라.”\n그가 어둠 속으로 사라졌다.", "quest": {"id": "yeonrak", "stage": "end_quit"}}}]};
QUEST_EVENTS["qb_tail"] = {"title": "장수통의 그림자", "kind": "quest", "loc": "bs_jangsu", "text": "장수통 큰길. 덕배가 다음 배 시간을 알리러 약방에 들른다는 날이다.\n길 건너 양품점 앞에 중절모를 쓴 사내가 서 있다. 같은 얼굴을 어제 부두에서도, 그제 초량 우물가에서도 보았다.\n사내가 약방 쪽을 힐끔거리며 수첩에 무언가를 적는다. 그러다 담배를 사러 가게로 들어간다.\n약방 안에서는 덕배가 아직 아무것도 모른 채 주인과 이야기를 나누고 있다.", "options": [{"label": "사내를 미행해 정체를 알아낸다", "check": {"stat": "int", "diff": "normal"}, "ok": {"text": "사내를 따라 수상경찰서 뒷문까지 갔다. 그가 문지기에게 수첩을 보여 주고 들어간다. 밀정이다.\n창 너머로 들은 한마디. “모레 출항 전에 화부 숙소를 덮친다.”\n아직 하루가 남았다.", "quest": {"id": "yeonrak", "stage": "warned", "wait": 0}}, "ng": {"text": "골목을 두 번 돌았을 때, 사내가 사라졌다. 돌아서니 바로 등 뒤에 서 있다.\n“나를 따라오는 이유가 뭐요?” 사내가 품에 손을 넣는다.", "fight": "hyungsa", "dist": 1.5, "questFight": {"id": "yeonrak", "win": "late", "other": "late", "wait": 0}}}, {"label": "곧장 약방으로 뛰어든다", "check": {"stat": "agi", "diff": "hard"}, "ok": {"text": "사내가 가게에 들어간 틈에 길을 건너 약방 뒷문으로 들어갔다.\n“밀정이 붙었소. 숙소도 알 거요.” 덕배의 얼굴이 굳는다.\n“…그라믄 이번 배에 다 태워야겠다. 꾸러미하고, 쫓기는 학생 하나도.\"", "quest": {"id": "yeonrak", "stage": "warned", "wait": 0}}, "ng": {"text": "길을 건너다 전차에 막혔다. 전차가 지나가고 보니 사내가 약방 문 앞에 서 있다.\n덕배가 뒷문으로 빠져나가는 것이 보였다. 사내가 호루라기를 꺼낸다.", "fx": {"heat": 1}, "quest": {"id": "yeonrak", "stage": "late", "wait": 0}}}, {"label": "모른 척한다", "ok": {"text": "사내를 못 본 척 지나쳤다.\n사흘 뒤, 장터에서 소문을 들었다. 연락선 화부 하나가 숙소에서 끌려갔다고.", "quest": {"id": "yeonrak", "stage": "caught", "wait": 6}}}]};
QUEST_EVENTS["qb_ship"] = {"title": "출항하는 밤", "kind": "quest", "loc": "bs_pier", "text": "자정 가까운 잔교. 시모노세키행 연락선이 기적을 한 번 울린다. 출항까지 한 시진.\n덕배가 석탄 창고 그늘에서 손짓한다. 그 옆에 교복을 벗고 노동자 옷을 걸친 앳된 청년이 떨고 있다. 쫓기는 학생이다.\n“이 아는 시모노세키 거쳐 상해로 간다. 꾸러미도 같이.” 덕배가 부두 쪽을 가리킨다. 승선구 앞에 수상경찰 넷이 등불을 들고 서 있다. “근데 저기를 지나야 된다.”\n석탄 짐꾼들이 줄지어 배로 오르고 있다.", "options": [{"label": "학생을 석탄 짐꾼으로 꾸며 태운다", "check": {"stat": "str", "diff": "normal"}, "ok": {"text": "학생 얼굴에 석탄 가루를 문지르고, 둘이 석탄 자루를 하나씩 졌다. 꾸러미는 자루 속에.\n등불이 얼굴을 훑고 지나간다. 수상경찰이 고개를 돌린다. “빨리빨리 올라가!”\n배 밑창에 자루를 내려놓고 내려오며, 덕배와 짧게 눈을 맞췄다. 기적이 길게 울렸다.", "fx": {"hp": -2}, "quest": {"id": "yeonrak", "stage": "success", "wait": 7}}, "ng": {"text": "자루가 무거워 학생이 휘청거렸다. 꾸러미가 자루 틈으로 빠져 바닥에 떨어진다.\n“거기! 그 자루 내려놔!” 등불이 일제히 이쪽을 향한다.", "fight": "patrol_pair", "dist": 2, "questFight": {"id": "yeonrak", "win": "success", "other": "caught", "wait": 6}}}, {"label": "반대편 창고에서 소동을 일으킨다", "check": {"stat": "int", "diff": "normal"}, "ok": {"text": "반대편 창고 앞에서 기름통을 걷어차고 “불이야!” 하고 외쳤다.\n수상경찰들이 그쪽으로 몰려가는 사이, 덕배와 학생이 승선구를 빠져나갔다.\n배가 부두를 떠난 뒤에야 숨을 돌렸다.", "fx": {"heat": 2}, "quest": {"id": "yeonrak", "stage": "success", "wait": 7}}, "ng": {"text": "소동은 컸지만 수상경찰 둘은 승선구를 지켰다.\n그리고 소리친 당신 쪽으로 등불이 다가온다. “방금 소리친 놈 누구냐!\"", "fight": "patrol_pair", "dist": 3, "questFight": {"id": "yeonrak", "win": "success", "other": "caught", "wait": 6}}}]};
QUEST_EVENTS["qb_raid"] = {"title": "화부 숙소 급습", "kind": "quest", "loc": "bs_pier", "text": "부두 뒤편 화부 숙소. 판자 벽 사이로 등불 그림자가 어지럽게 흔들린다. 수상경찰이 이미 들이닥쳤다.\n안에서 덕배의 고함. “꾸러미 태워라! 아는 뒷문으로!”\n앞문에는 수상경찰 셋이 곤봉을 들고 서 있고, 뒤쪽 방파제 쪽으로도 발소리가 다가온다.\n뒷문 앞 갯바위 쪽에는 아직 아무도 없다. 오래가지는 않을 것이다.", "options": [{"label": "앞문을 막아선다", "ok": {"text": "앞문으로 뛰어들어 수상경찰들 앞을 막아섰다.\n“비켜라, 조센징!” 등 뒤에서 덕배가 외친다. “니까지 와 이라노!”\n“어서 가소!\"", "ambush": true, "fight": "raid_light", "questFight": {"id": "yeonrak", "win": "success", "other": "caught", "wait": 6}}}, {"label": "덕배와 학생을 데리고 갯바위로 빠진다", "check": {"stat": "agi", "diff": "hard"}, "ok": {"text": "연기 자욱한 숙소로 뛰어들어 둘의 팔을 잡아끌었다. 뒷문을 박차고 갯바위를 타고 내려갔다.\n밀물에 발목까지 잠기며 방파제 밑을 돌아 영도 쪽 나룻배에 올랐다.\n덕배가 젖은 꾸러미를 품에서 꺼낸다. “다 젖었지만… 아직 읽을 수는 있다.\"", "fx": {"heat": 2}, "quest": {"id": "yeonrak", "stage": "success", "wait": 7}}, "ng": {"text": "갯바위에서 학생이 미끄러졌다. 덕배가 그를 붙잡는 사이 수상경찰이 들이닥쳤다.\n“니는 가라!” 덕배가 당신을 바다 쪽으로 떠민다. 물에 뛰어들어 겨우 빠져나왔다.\n돌아본 갯바위 위에서, 덕배가 수갑을 차고 있었다.", "fx": {"heat": 2, "hp": -2}, "quest": {"id": "yeonrak", "stage": "caught", "wait": 6}}}, {"label": "발길을 돌린다", "ok": {"text": "창고 그늘에 숨어 모든 것을 지켜보았다.\n덕배와 학생이 끌려 나오고, 숙소에서 꾸러미 타는 연기가 피어올랐다. 덕배가 끌려가며 부두를 둘러본다.\n트럭이 떠나고, 부두에는 파도 소리만 남았다.", "quest": {"id": "yeonrak", "stage": "caught", "wait": 6}}}]};
QUEST_EVENTS["qb_prison"] = {"title": "부산형무소 면회", "kind": "quest", "loc": "bs_home", "text": "부산형무소 면회실. 철망 너머에 덕배가 앉아 있다. 석탄 가루 대신 멍이 얼굴을 덮었다. 손가락 두 개에 붕대가 감겨 있다.\n그래도 덕배가 이를 드러내고 웃는다.\n“왔나. 밥은 묵고 다니나.”\n간수가 하품을 하며 시계를 본다. 덕배가 목소리를 낮춘다.\n“학생은 잡혔고, 꾸러미는 다 탔다. 근데 시모노세키 쪽 동지들은 아직 모른다. 누가 알려 줘야 되는데….\"", "options": [{"label": "간수에게 뒷돈을 찔러 준다", "cost": {"money": 10}, "ok": {"text": "면회를 마치고 조선인 간수에게 지폐를 쥐여 주었다. “…증거가 다 탔다 카니, 오래는 못 잡아 둘 기다.”\n한 달 뒤, 덕배가 형무소 문을 나섰다. 다른 배 화부 자리를 얻었다고 했다.\n헤어지며 그가 손에 무언가를 쥐여 준다. 배에서 쓰던 사냥용 엽총이다. “바다 위에선 이게 필요할 때가 있다.\"", "weapon": "hunting", "fx": {"ammo": 4, "heat": 1}, "quest": {"id": "yeonrak", "stage": "end_freed"}}}, {"label": "시모노세키에 소식을 전해 주겠다고 한다", "ok": {"text": "덕배가 불러 주는 이름과 주소를 머리에 새겼다. 종이에 적지 않는 것이 규칙이라 했다.\n“고맙다. 니는 끝까지 우리 편이다.”\n그날 밤 부두 선원 하나에게 말을 전했다. 바다 건너로 소식이 넘어갔다.", "fx": {"int": 2, "heat": 1}, "quest": {"id": "yeonrak", "stage": "end_letter"}}}, {"label": "고개를 숙이고 돌아선다", "ok": {"text": "“미안하오.” 그 말밖에 나오지 않았다.\n덕배가 손을 내젓는다. “미안할 거 없다. 함지에 꾸러미 숨겨 준 그날, 니는 할 일 다 했다. 몸조심해라.\"", "quest": {"id": "yeonrak", "stage": "end_prison"}}}]};
QUEST_EVENTS["qb_epilogue"] = {"title": "상해에서 온 엽서", "kind": "quest", "loc": "bs_home", "text": "초량 판잣집 문틈에 엽서 한 장이 끼워져 있다. 중국 우표, 상해 소인. 그림은 황포강의 배들.\n뒷면에는 짧은 글.\n〈무사히 도착했습니다. 짐도 잘 받았다고 합니다. 바다 건너에도 같은 마음이 있다는 걸 잊지 않겠습니다. — 학생〉\n그날 저녁, 덕배가 술 한 병을 들고 찾아왔다. 이번엔 웃는 얼굴이다.\n“니 덕에 한 건 했다. 뭐라도 갚아야 내 속이 편하다. 뭐 해 주꼬?\"", "options": [{"label": "덕배의 선물을 받는다", "ok": {"text": "덕배가 기름종이에 싼 것을 내민다. 배에서 쓰던 사냥용 엽총과 탄환 한 줌이다.\n“바다 위에선 별일이 다 생긴다. 니도 하나쯤은 있어야 된다.\"", "weapon": "hunting", "fx": {"ammo": 6}, "quest": {"id": "yeonrak", "stage": "end_success"}}}, {"label": "뱃사람 일을 배운다", "ok": {"text": "“나도 배 일 좀 가르쳐 주소.”\n덕배가 웃으며 그날부터 부두 하역과 배 밑창 화부 일을 가르쳐 주었다. 석탄 삽질에 어깨가 단단해졌다.", "fx": {"str": 2, "con": 1}, "quest": {"id": "yeonrak", "stage": "end_success"}}}, {"label": "다음 배도 돕겠다고 약속한다", "ok": {"text": "“갚을 건 없소. 다음 배 뜰 때도 부르시오.”\n덕배가 당신 손을 꽉 쥔다. 석탄 가루가 밴 손이다.\n“부두에서 ‘석탄 한 삽’ 카면 우리 사람들이 알아듣는다. 잊지 마래이.\"", "fx": {"int": 2, "heat": 1}, "quest": {"id": "yeonrak", "stage": "end_success"}}}]};
QUEST_EVENTS["qb_revenge"] = {"title": "“부두의 개”", "kind": "quest", "loc": "bs_pier", "text": "부두 창고 뒤. 하역을 마친 인부 넷이 갈고리를 든 채 길을 막는다.\n맨 앞 사내가 갈고리 끝으로 당신을 가리킨다.\n“니가 그 꾸러미 수상경찰한테 갖다 바친 놈이제?”\n뒤에 선 늙은 인부가 침을 뱉는다. “덕배는 지금 형무소에서 손톱이 다 빠졌다 카더라. 그 돈은 잘 묵었나?\"", "options": [{"label": "가진 돈을 내놓으며 사죄한다", "cost": {"money": 8}, "ok": {"text": "주머니를 털어 내밀었다. “미안하오. 그땐 나도 살아야 했소.”\n사내가 돈을 받아 든다. “덕배 옥바라지에 쓰꾸마. 다시는 이 부두에 얼씬도 하지 마라.\"", "quest": {"id": "yeonrak", "stage": "end_betray"}}}, {"label": "맞선다", "ok": {"text": "“살자고 한 일이오!”\n“덕배도 살고 싶었다!” 인부들이 갈고리를 고쳐 쥐고 달려든다.", "ambush": true, "fight": "wangpae_gang", "questFight": {"id": "yeonrak", "win": "end_betray", "other": "end_betray"}}}, {"label": "짐더미 사이로 달아난다", "check": {"stat": "agi", "diff": "normal"}, "ok": {"text": "쌀가마 더미 사이로 몸을 던져 빠져나왔다.\n등 뒤에서 외침이 따라왔다. “부산 바닥에서 니 얼굴 다 안다!\"", "fx": {"heat": 1}, "quest": {"id": "yeonrak", "stage": "end_betray"}}, "ng": {"text": "짐더미 끝은 바다였다. 돌아서니 인부들이 반원을 그리며 다가온다.\n“어디로 갈 끼고.\"", "fight": "wangpae_gang", "dist": 1, "questFight": {"id": "yeonrak", "win": "end_betray", "other": "end_betray"}}}]};
