QUESTS["tonggam"] = {"name": "『망국통감』 편찬", "start": "qt_start", "startChance": 0.06, "years": [1910, 1919], "loc": "bukchon", "followChance": 0.08, "stages": {"met": {"event": "qt_meet", "place": "윤 진사의 사랑방", "sub": "보따리의 주인이 사람을 보냈다"}, "gather": {"event": "qt_gather", "place": "종로 고서점", "sub": "마지막 자료를 구하러 간다"}, "warned": {"event": "qt_move", "place": "원고를 국경 너머로", "sub": "헌병보다 먼저 원고를 내보내야 한다", "chance": 0.7}, "late": {"event": "qt_raid", "place": "사랑방 급습", "sub": "헌병이 사랑방으로 향했다", "chance": 0.9}, "caught": {"event": "qt_prison", "place": "태형 뒤의 윤 진사", "sub": "윤 진사가 끌려가 매를 맞았다"}, "success": {"event": "qt_epilogue", "place": "상해에서 온 책", "sub": "책이 찍혀 나왔다는 기별"}, "betray": {"event": "qt_revenge", "place": "", "sub": ""}}};
QUEST_EVENTS["qt_start"] = {"title": "불타는 서고", "kind": "quest", "loc": "bukchon", "text": "계동 골목 끝 서당 마당에서 연기가 오른다. 헌병 둘이 서고의 책을 한 아름씩 끌어내 마당 한가운데 불더미에 던져 넣는다. 『대한매일신보』 묶음이, 손으로 베낀 의병 격문이, 붓으로 쓴 일기책이 불길에 말려 들어간다.\n갓을 쓴 늙은 유생이 헌병의 팔에 매달린다. “그건 역사요! 불사를 물건이 아니오!”\n헌병이 유생을 밀쳐 넘어뜨린다. 넘어진 유생의 소매에서 보자기 꾸러미 하나가 굴러 담장 밑으로 떨어진다.\n유생이 당신과 눈을 맞춘다. 그리고 아주 작게, 꾸러미 쪽으로 턱을 든다.", "options": [{"label": "꾸러미를 몰래 주워 품에 넣는다", "check": {"stat": "agi", "diff": "normal"}, "ok": {"text": "헌병들이 불더미를 들쑤시는 사이, 담장 밑의 꾸러미를 주워 두루마기 안에 넣었다.\n대문을 나설 때까지 아무도 돌아보지 않았다.\n그날 밤 꾸러미를 풀어 보니, 한 장 한 장 붓으로 베낀 글이다. 〈을사년 시월, 대한의 국권이 칼끝에 넘어가니….〉 맨 끝에 적힌 이름은 ‘윤 진사’.", "fx": {"heat": 1}, "quest": {"id": "tonggam", "stage": "met", "wait": 5}}, "ng": {"text": "꾸러미를 집어 드는 순간 헌병 하나가 돌아섰다.\n“그게 뭐냐! 이리 내놔!” 총검이 이쪽을 향한다.", "fight": "kenpei", "dist": 2, "questFight": {"id": "tonggam", "win": "met", "other": "met", "wait": 5}}}, {"label": "헌병에게 꾸러미를 가리킨다", "ok": {"text": "담장 밑을 손가락으로 가리켰다. 헌병이 꾸러미를 집어 들고 펼쳐 보더니 불더미에 던진다.\n헌병이 당신 어깨를 두드리며 동전을 쥐여 준다. “요시. 협조하는 조선인은 대접을 받는다.”\n늙은 유생이 땅바닥에 앉은 채 불타는 종이를 바라본다. 울지도 않았다.", "fx": {"money": 4, "heat": -1}, "quest": {"id": "tonggam", "stage": "betray", "wait": 7}}}, {"label": "못 본 척 지나간다", "ok": {"text": "고개를 돌리고 골목을 빠져나왔다.\n등 뒤에서 종이 타는 냄새가 오래 따라왔다. 그날 계동 하늘은 저녁까지 잿빛이었다.", "quest": {"id": "tonggam", "stage": "end_ignored"}}}]};
QUEST_EVENTS["qt_meet"] = {"title": "윤 진사의 사랑방", "kind": "quest", "loc": "bukchon", "text": "며칠 뒤, 댕기 머리 아이가 쪽지를 건넨다. 〈보자기 주인이 뵙기를 청하오.〉\n안국동 낡은 기와집 사랑방. 문을 열자 먹 냄새가 훅 끼친다. 상투를 튼 유생 넷이 방바닥 가득 종이를 펼쳐 놓고 붓을 놀리고 있다. 그날의 늙은 유생, 윤 진사가 상석에서 몸을 일으킨다.\n“그대가 내 보자기를 건졌구려. 앉으시오.”\n윤 진사가 펼쳐 놓은 원고를 손바닥으로 쓸어 보인다.\n“갑신년부터 경술년 국치까지, 나라가 어찌 빼앗겼는지를 적는 책이오. 『망국통감(亡國痛鑑)』이라 하였소. 총독부는 조선이 스스로 원해 합쳐졌다고 가르칠 것이오. 그러니 누군가는 사실을 적어 두어야 하오.”\n그가 한숨을 쉰다. “허나 헌병이 서고를 다 태워 버려, 옛 신문과 의병들의 기록이 모자라오.\"", "options": [{"label": "종로 헌책방을 돌며 옛 신문을 모은다", "check": {"stat": "int", "diff": "normal"}, "ok": {"text": "종로 헌책방과 고물상을 돌며 벽지로 쓰려고 묶어 둔 옛 신문 더미를 헐값에 사들였다. 『황성신문』, 『대한매일신보』.\n윤 진사가 신문을 한 장 한 장 펼쳐 보더니 손을 떤다. “이것이… 시일야방성대곡이 실린 호로구려.”\n“마지막으로 하나가 남았소. 종로 고서점 주인이 의병들의 진중일기를 숨겨 두었다 하오.\"", "fx": {"edu": 1}, "quest": {"id": "tonggam", "stage": "gather", "wait": 4}}, "ng": {"text": "고물상 주인이 신문 더미를 넘기며 주위를 살폈다. 그 사이 헌병 보조원이 가게로 들어선다.\n“옛 신문을 왜 사 모으나? 불온한 놈이구먼.\"", "fight": "kenpei", "dist": 2, "questFight": {"id": "tonggam", "win": "gather", "other": "gather", "wait": 4}}}, {"label": "종이와 먹값을 보탠다", "cost": {"money": 5}, "ok": {"text": "종이 다섯 권과 먹 열 장 값을 윤 진사 앞에 내놓았다.\n유생들이 서로 얼굴을 보다가 일제히 고개를 숙인다. 윤 진사가 웃는다. “글 아는 이보다 마음 아는 이가 귀한 세상이오.”\n“이제 종로 고서점에 숨겨 둔 의병 진중일기만 구하면 되오.\"", "fx": {"heat": 1}, "quest": {"id": "tonggam", "stage": "gather", "wait": 4}}}, {"label": "발을 뺀다", "ok": {"text": "“송구하오. 저는 글도 짧고, 목숨도 아깝소.”\n윤 진사가 고개를 끄덕인다. “부끄러워할 것 없소. 보자기를 건져 준 것만으로 큰일을 한 것이오.”\n사랑방 문을 나서는데, 붓 놀리는 소리가 등 뒤에서 이어졌다.", "quest": {"id": "tonggam", "stage": "end_quit"}}}]};
QUEST_EVENTS["qt_gather"] = {"title": "종로 고서점", "kind": "quest", "loc": "jongno", "text": "종로 뒷골목 고서점. 천장까지 쌓인 책 더미 사이로 먼지가 햇빛에 떠다닌다.\n안경 쓴 주인 영감이 당신을 보더니 말없이 책장 하나를 밀어낸다. 그 뒤 벽 틈에서 기름종이로 싼 공책 세 권이 나온다.\n“을사년 이후 경기·강원 의병들의 진중일기요. 싸우다 죽은 이들 이름이 다 적혀 있소. 윤 진사께 전하시오.”\n그때 가게 밖에서 인기척. 흰 두루마기를 입은 사내 하나가 창 밖에서 책을 고르는 척 귀를 기울이고 있다. 사흘 전 사랑방 골목에서도 본 얼굴이다.", "options": [{"label": "사내를 따라가 정체를 알아낸다", "check": {"stat": "int", "diff": "normal"}, "ok": {"text": "공책을 품에 넣고, 서점을 떠나는 사내를 멀찍이 따라갔다. 사내가 들어간 곳은 헌병분대 뒷문이었다. 밀정이다.\n창 너머 대화가 들렸다. “안국동 윤가 사랑방, 이레 뒤에 친다.”\n아직 이레가 남았다.", "quest": {"id": "tonggam", "stage": "warned", "wait": 0}}, "ng": {"text": "모퉁이를 두 번 돌았을 때 사내가 사라졌다. 돌아서니 헌병이 서 있다.\n“책 보따리를 들고 어딜 그리 바삐 가나?\"", "fight": "kenpei", "dist": 1.5, "questFight": {"id": "tonggam", "win": "late", "other": "late", "wait": 0}}}, {"label": "곧장 윤 진사에게 달려간다", "check": {"stat": "agi", "diff": "hard"}, "ok": {"text": "뒷문으로 빠져 골목을 가로질렀다. 사랑방에 뛰어들어 숨을 고르며 말을 전했다.\n윤 진사의 얼굴이 굳는다. “밀정이 붙었다면 오래 못 숨기오. 원고를 국경 너머로 내보내야겠소. 상해에 찍어 줄 동지가 있소.\"", "quest": {"id": "tonggam", "stage": "warned", "wait": 0}}, "ng": {"text": "골목을 돌아 나오는데 등 뒤에 발소리가 붙었다. 떼어 내려 북촌을 한 바퀴 돌고 나니 해가 졌다.\n안국동에 닿았을 때, 사랑방 쪽에서 호루라기 소리가 들렸다.", "fx": {"heat": 1}, "quest": {"id": "tonggam", "stage": "late", "wait": 0}}}, {"label": "못 본 척하고 공책만 전한다", "ok": {"text": "사내를 모른 척하고 공책만 윤 진사에게 전했다.\n열흘 뒤, 북촌에 소문이 돌았다. 안국동 기와집에 헌병이 들이닥쳐 늙은 진사를 끌고 갔다고.", "quest": {"id": "tonggam", "stage": "caught", "wait": 6}}}]};
QUEST_EVENTS["qt_move"] = {"title": "원고를 국경 너머로", "kind": "quest", "loc": "station", "text": "새벽 경성역. 신의주행 첫 기차가 증기를 뿜는다. 개찰구 앞에서 헌병들이 짐을 하나하나 풀어 보고 있다. 무단통치기의 헌병은 이유 없이도 사람을 끌고 간다.\n윤 진사의 제자인 젊은 유생이 떨리는 손으로 보따리를 끌어안고 서 있다. 그 안에 『망국통감』 원고 전부가 들었다.\n“신의주에서 압록강만 건너면 상해로 가는 길이 있소. 허나 저 검문을….”\n그가 당신을 본다. “원고가 압수되면 십 년 공부가 재가 되오.\"", "options": [{"label": "원고를 족보 사이에 끼워 넘긴다", "check": {"stat": "int", "diff": "normal"}, "ok": {"text": "원고를 몇 장씩 나누어 낡은 족보 책장 사이사이에 끼웠다. 겉으로 보기엔 그냥 시골 양반의 족보다.\n헌병이 족보를 펼치더니 지루한 얼굴로 덮는다. “가.”\n기차가 출발한다. 창밖으로 젊은 유생이 몇 번이고 고개를 숙였다.", "quest": {"id": "tonggam", "stage": "success", "wait": 7}}, "ng": {"text": "족보를 넘기던 헌병의 손이 멈춘다. 끼워 둔 원고 한 장이 바닥에 떨어졌다.\n“이건 족보가 아니군. 불온 문서다!\"", "fight": "kenpei_pair", "dist": 2, "questFight": {"id": "tonggam", "win": "success", "other": "caught", "wait": 6}}}, {"label": "검문 줄에서 소동을 일으킨다", "check": {"stat": "agi", "diff": "normal"}, "ok": {"text": "뒤쪽에서 보따리를 일부러 엎었다. 놋그릇이 쏟아지며 요란한 소리가 났다.\n헌병들이 그쪽을 보는 사이, 젊은 유생이 개찰구를 빠져나가 기차에 올랐다.", "fx": {"heat": 2}, "quest": {"id": "tonggam", "stage": "success", "wait": 7}}, "ng": {"text": "소동을 일으켰지만 헌병 하나는 개찰구를 떠나지 않았다.\n그리고 엎어진 보따리의 주인을 찾는다. “방금 그놈, 이리 와!\"", "fight": "kenpei_pair", "dist": 3, "questFight": {"id": "tonggam", "win": "success", "other": "caught", "wait": 6}}}]};
QUEST_EVENTS["qt_raid"] = {"title": "사랑방 급습", "kind": "quest", "loc": "bukchon", "text": "안국동 기와집 대문이 부서져 있다. 마당에서 헌병들이 사랑방 문을 걷어차고, 안에서 유생들의 고함이 들린다.\n“원고부터 태워라! 이름 적힌 장부터!” 윤 진사의 목소리다. 창호지 너머로 불빛이 번진다.\n대문 앞에 헌병 둘이 총검을 들고 서 있다. 뒤뜰 장독대 쪽 쪽문은 아직 열려 있다.", "options": [{"label": "대문 앞을 막아선다", "ok": {"text": "헌병들 앞으로 뛰어들어 대문을 막아섰다.\n“비켜라! 너도 한패냐!” 등 뒤에서 윤 진사가 외친다. “그대까지 다치면 아니 되오!”\n“어서 원고를 들고 가시오!\"", "ambush": true, "fight": "kenpei_pair", "questFight": {"id": "tonggam", "win": "success", "other": "caught", "wait": 6}}}, {"label": "원고를 안고 쪽문으로 빠진다", "check": {"stat": "agi", "diff": "hard"}, "ok": {"text": "연기 자욱한 사랑방에 뛰어들어 타다 남은 원고 뭉치를 끌어안았다. 쪽문을 지나 장독대를 밟고 담을 넘었다.\n북악 기슭 바위 그늘에 숨어 원고를 펼쳐 보니, 반은 탔지만 반은 남았다.\n그 반을 들고 상해로 갈 사람을 찾는 데 한 달이 걸렸다.", "fx": {"heat": 2}, "quest": {"id": "tonggam", "stage": "success", "wait": 7}}, "ng": {"text": "원고를 안고 담을 넘다 헌병에게 발목을 잡혔다. 원고 뭉치가 마당에 흩어진다.\n몸부림쳐 빠져나왔지만, 돌아본 마당에서 윤 진사가 포승에 묶이고 있었다.", "fx": {"heat": 2, "hp": -2}, "quest": {"id": "tonggam", "stage": "caught", "wait": 6}}}, {"label": "발길을 돌린다", "ok": {"text": "골목 모퉁이 그늘에서 모든 것을 지켜보았다.\n불길이 사랑방 지붕을 넘고, 유생들이 하나씩 끌려 나오고, 마지막으로 윤 진사가 나왔다. 그는 끌려가면서도 갓을 바로 썼다.", "quest": {"id": "tonggam", "stage": "caught", "wait": 6}}}]};
QUEST_EVENTS["qt_prison"] = {"title": "태형 뒤의 윤 진사", "kind": "quest", "loc": "bukchon", "text": "윤 진사는 헌병분대에서 태형 아흔 대를 맞고 풀려났다. 조선인에게만 치는 매다.\n안국동 기와집 건넌방. 윤 진사가 엎드린 채 앓고 있다. 등에서 진물이 배어 나온다. 그래도 당신을 보자 몸을 일으키려 한다.\n“왔구려. 원고는… 다 탔소.” 그가 숨을 고른다. “허나 내 머릿속에는 아직 남아 있소. 늙은이 기억이 언제까지 갈지 모르지만.\"", "options": [{"label": "약값을 대고 의원을 부른다", "cost": {"money": 10}, "ok": {"text": "한의원을 불러 고약을 붙이고 탕약을 지었다. 열흘 뒤, 윤 진사가 처음으로 일어나 앉았다.\n“빚을 졌구려.” 그가 서랍에서 약 꾸러미를 꺼내 건넨다. “의원이 남기고 간 것이오. 그대가 더 쓸 데가 많을 게요.\"", "fx": {"medkit": 2, "heat": 1}, "quest": {"id": "tonggam", "stage": "end_freed"}}}, {"label": "윤 진사의 기억을 받아 적는다", "ok": {"text": "밤마다 윤 진사 머리맡에 앉아, 그가 불러 주는 대로 받아 적었다. 을사년의 칼끝, 정미년의 군대 해산, 경술년의 그날.\n한 달 뒤 공책 한 권이 찼다. 윤 진사가 웃는다. “이제 나는 죽어도 되겠소.\"", "fx": {"int": 2, "edu": 1, "heat": 1}, "quest": {"id": "tonggam", "stage": "end_letter"}}}, {"label": "고개를 숙이고 돌아선다", "ok": {"text": "“송구하오.” 그 말밖에 할 수 없었다.\n윤 진사가 손을 젓는다. “보자기를 건져 준 그날, 그대는 할 일을 다 했소. 살아남으시오. 기억하는 사람이 있어야 하오.\"", "quest": {"id": "tonggam", "stage": "end_prison"}}}]};
QUEST_EVENTS["qt_epilogue"] = {"title": "상해에서 온 책", "kind": "quest", "loc": "bukchon", "text": "한겨울, 셋방 문 앞에 짚신 장수 하나가 짚신 꾸러미를 두고 간다. 꾸러미 속, 짚신 바닥에 얇은 책 한 권이 숨겨져 있다.\n『망국통감(亡國痛鑑)』. 상해에서 찍었다는 표지. 첫 장을 펼치면 윤 진사의 서문이 있다.\n〈나라는 망하였으나 역사는 망하지 아니하였다. 이 책을 읽는 이가 있는 한.〉\n그날 저녁, 윤 진사가 지팡이를 짚고 셋방을 찾아왔다. 눈가가 붉다.\n“스무 권이 국경을 넘어 들어왔소. 그 첫 권을 그대에게 주려 하오. 그리고 무엇이든 청하시오.\"", "options": [{"label": "책을 받아 밤새 읽는다", "ok": {"text": "호롱불 아래서 밤새 읽었다. 이름 모를 의병들의 마지막 날, 헤이그로 간 이들의 편지, 국치의 그날 종로의 통곡.\n새벽이 되어 책을 덮었을 때, 세상을 보는 눈이 달라져 있었다.", "fx": {"int": 2, "edu": 1}, "quest": {"id": "tonggam", "stage": "end_success"}}}, {"label": "서당에서 아이들에게 읽힌다", "ok": {"text": "“이 책은 내가 읽고 덮을 것이 아니오. 아이들이 읽어야 하오.”\n윤 진사가 크게 웃는다. 그날부터 밤마다 서당 뒷방에서 아이들에게 한 장씩 읽어 주었다. 문밖에 망보는 아이를 세워 두고.", "fx": {"edu": 2, "heat": 1}, "quest": {"id": "tonggam", "stage": "end_success"}}}, {"label": "다음 책도 돕겠다고 약속한다", "ok": {"text": "“청할 것은 없소. 다음 권을 엮을 때 다시 부르시오.”\n윤 진사가 당신의 손을 두 손으로 감싼다. 먹물이 밴 손이다.\n“안국동 고서점 주인에게 ‘통감 한 질’이라 하시오. 우리 사람들이 알아들을 것이오.\"", "fx": {"int": 2, "heat": 1}, "quest": {"id": "tonggam", "stage": "end_success"}}}]};
QUEST_EVENTS["qt_revenge"] = {"title": "“서고를 판 자”", "kind": "quest", "loc": "bukchon", "text": "해 진 골목. 망건을 쓴 젊은 유생 셋이 길을 막는다. 하나는 손에 목검을 들었다.\n“계동 서당에서 헌병에게 보자기를 가리킨 자, 그대가 맞소?”\n가운데 유생의 목소리가 떨린다. “그 보자기에 우리 스승님이 십 년을 들인 원고가 있었소. 스승님은 그날 이후 붓을 꺾으셨소.\"", "options": [{"label": "가진 돈을 내놓으며 사죄한다", "cost": {"money": 8}, "ok": {"text": "가진 돈을 내밀고 고개를 숙였다. “그땐… 나도 살아야 했소.”\n유생이 돈을 받아 든다. “이것으로 종이를 사겠소. 스승님이 다시 붓을 드시도록. 허나 그대를 용서하지는 않겠소.\"", "quest": {"id": "tonggam", "stage": "end_betray"}}}, {"label": "맞선다", "ok": {"text": "“글줄이나 읽는 자들이 사람을 치려 드오?”\n“글을 읽었기에 참을 수 없는 것이오!” 유생들이 달려든다.", "ambush": true, "fight": "youths", "questFight": {"id": "tonggam", "win": "end_betray", "other": "end_betray"}}}, {"label": "골목으로 달아난다", "check": {"stat": "agi", "diff": "normal"}, "ok": {"text": "옆 골목으로 몸을 던져 담을 넘었다. 겨우 따돌렸다.\n등 뒤에서 외침이 따라왔다. “북촌 사람들이 다 그대 얼굴을 기억할 것이오!\"", "fx": {"heat": 1}, "quest": {"id": "tonggam", "stage": "end_betray"}}, "ng": {"text": "골목 끝이 막혀 있었다. 유생들이 숨을 몰아쉬며 다가온다.\n“도망칠 곳은 없소.\"", "fight": "youths", "dist": 1, "questFight": {"id": "tonggam", "win": "end_betray", "other": "end_betray"}}}]};
